#![cfg(feature = "legacy-import")]
//! Golden oracle generated by scripts/generate-rust-engine-fixtures.ts from the
//! original deterministic TypeScript engine. No JS runtime is needed to run tests.
use avalon_server::{bots::codec as bots, engine::codec as engine};
use serde_json::{Value, json};
use sha2::{Digest, Sha256};
fn canonical(v: &Value) -> String {
    fn append(out: &mut String, v: &Value) {
        match v {
            Value::Object(map) => {
                out.push('{');
                let mut keys: Vec<_> = map.keys().collect();
                keys.sort();
                for (i, k) in keys.iter().enumerate() {
                    if i > 0 {
                        out.push(',');
                    }
                    out.push_str(&serde_json::to_string(k).unwrap());
                    out.push(':');
                    append(out, &map[*k]);
                }
                out.push('}');
            }
            Value::Array(a) => {
                out.push('[');
                for (i, v) in a.iter().enumerate() {
                    if i > 0 {
                        out.push(',');
                    }
                    append(out, v);
                }
                out.push(']');
            }
            _ => out.push_str(&v.to_string()),
        }
    }
    let mut out = String::new();
    append(&mut out, v);
    out
}
fn hash(v: &Value) -> String {
    format!("{:x}", Sha256::digest(canonical(v).as_bytes()))
}
#[test]
fn engine_transitions_and_private_projections_match_typescript() {
    let traces: Vec<Value> =
        serde_json::from_str(include_str!("fixtures/engine-traces.json")).unwrap();
    for trace in traces {
        let name = trace["name"].as_str().unwrap();
        let mut state = engine::create_legacy_game(&trace["input"]).unwrap();
        assert_eq!(hash(&state), trace["initial"], "{name}: create");
        for (i, step) in trace["steps"].as_array().unwrap().iter().enumerate() {
            if let Some(bot) = step.get("bot") {
                let view = engine::project(&state, bot["by"].as_str().unwrap());
                let decision = bots::decide_legacy_detailed(
                    &view,
                    bot["by"].as_str().unwrap(),
                    bot["action"].as_str().unwrap(),
                    bot["seed"].as_str().unwrap(),
                )
                .unwrap();
                assert_eq!(decision["event"], step["event"], "{name} {i}: live bot");
                assert_eq!(
                    decision["reason"], bot["reason"],
                    "{name} {i}: live bot reason"
                );
                assert_eq!(
                    decision.get("hypotheses"),
                    bot.get("hypotheses"),
                    "{name} {i}: live bot hypotheses"
                );
            }
            let owned = engine::reduce_owned(
                state.clone(),
                &step["event"],
                step["now"].as_i64().unwrap(),
                step["seed"].as_str().unwrap(),
            );
            if let Err((_, returned)) = &owned {
                assert_eq!(
                    returned, &state,
                    "{name} {i}: rejected owned reducer mutated input"
                );
            }
            let result = engine::reduce_legacy(
                &state,
                &step["event"],
                step["now"].as_i64().unwrap(),
                step["seed"].as_str().unwrap(),
            );
            if let Some(expected) = step.get("error") {
                let err = result.expect_err(&format!("{name} {i}"));
                assert_eq!(json!(err), *expected, "{name} {i}: error");
            } else {
                let result = result.unwrap_or_else(|e| panic!("{name} {i}: {e}"));
                assert_eq!(
                    json!(result.effects),
                    step["effects"],
                    "{name} {i}: effects"
                );
                if hash(&result.state) != step["state"] {
                    std::fs::write(
                        "/tmp/actual-engine-state.json",
                        serde_json::to_string_pretty(&result.state).unwrap(),
                    )
                    .unwrap();
                    panic!(
                        "{name} step {i} event {}: state mismatch, actual written to /tmp/actual-engine-state.json",
                        step["event"]
                    );
                }
                assert_eq!(
                    owned.unwrap().state,
                    result.state,
                    "{name} {i}: owned reducer equality"
                );
                state = result.state;
                let mut viewers: Vec<String> = trace["input"]["players"]
                    .as_array()
                    .unwrap()
                    .iter()
                    .map(|p| p["id"].as_str().unwrap().to_owned())
                    .collect();
                viewers.push("observer".into());
                let views = engine::project_many(&state, &viewers);
                let index = i % viewers.len();
                assert_eq!(
                    views[index],
                    engine::project(&state, &viewers[index]),
                    "{name} {i}: batched projection"
                );
                let actual = Value::Array(views);
                if hash(&actual) != step["views"] {
                    std::fs::write(
                        "/tmp/actual-engine-views.json",
                        serde_json::to_string_pretty(&actual).unwrap(),
                    )
                    .unwrap();
                    panic!("{name} step {i}: projection mismatch");
                }
            }
        }
    }
}
#[test]
fn weighted_deals_match_typescript() {
    let cases: Vec<Value> =
        serde_json::from_str(include_str!("fixtures/weighted-roles.json")).unwrap();
    for (i, c) in cases.iter().enumerate() {
        let exclude = c
            .get("excluded")
            .map(|e| (e["playerId"].as_str().unwrap(), e["role"].as_str().unwrap()));
        let result = engine::weighted_roles_legacy(
            &c["players"],
            &c["deck"],
            &c["weights"],
            c["seed"].as_str().unwrap(),
            exclude,
        );
        assert_eq!(json!(result), c["result"], "weighted case {i}");
    }
}
#[test]
fn bot_policy_matches_typescript() {
    let cases: Vec<Value> =
        serde_json::from_str(include_str!("fixtures/bot-decisions.json")).unwrap();
    for (i, c) in cases.iter().enumerate() {
        let result = bots::decide_legacy_detailed(
            &c["view"],
            c["by"].as_str().unwrap(),
            c["action"].as_str().unwrap(),
            c["seed"].as_str().unwrap(),
        )
        .unwrap();
        assert_eq!(
            result["event"], c["result"]["event"],
            "bot {i} {} seed {}",
            c["action"], c["seed"]
        );
        assert_eq!(result["reason"], c["result"]["reason"], "bot reason {i}");
        assert_eq!(
            result.get("hypotheses"),
            c["result"].get("hypotheses"),
            "bot worlds {i}"
        );
        assert_eq!(
            result.get("consistent"),
            c["result"].get("consistent"),
            "bot consistency {i}"
        );
        if let Some(actual) = result["alternatives"].as_array() {
            let expected = c["result"]["alternatives"].as_array().unwrap();
            assert_eq!(actual.len(), expected.len(), "bot alternatives {i}");
            for alternative in actual {
                if let Some(reference) = expected.iter().find(|r| {
                    r.get("team") == alternative.get("team")
                        && r.get("target") == alternative.get("target")
                }) {
                    for field in ["score", "risk", "probability"] {
                        if let Some(a) = alternative.get(field).and_then(Value::as_f64) {
                            let b = reference[field].as_f64().unwrap();
                            assert!((a - b).abs() < 1e-10, "bot {i} {field}: {a} != {b}");
                        }
                    }
                } else {
                    // JS/Rust libm rounding can reorder mathematically tied
                    // candidates at the diagnostic top-five cutoff.
                    let cutoff = expected.last().unwrap()["score"].as_f64().unwrap();
                    assert!(
                        (alternative["score"].as_f64().unwrap() - cutoff).abs() < 1e-10,
                        "bot {i}: unexpected alternative"
                    );
                }
            }
        }
    }
}
